package com.ruoyi.web.biz;
import java.util.*;
import java.time.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import com.ruoyi.common.utils.SecurityUtils;
import com.ruoyi.common.exception.ServiceException;
@Service
public class PersonnelService {
 final EmployeeService employees; final JdbcTemplate db;
 public PersonnelService(EmployeeService e,CompanyOnboardingMapper mapper){employees=e;db=mapper.database();}
 long company(String permission){if(!employees.hasPermission(permission))throw new AccessDeniedException("无操作权限");return employees.manager("manage");}
 public Map<String,Object> detail(long id){company("biz:personnel:list");return employees.staffDetail(id);}
 void reason(String value){if(value==null||value.isBlank()||value.length()>500)throw new ServiceException("变更原因必填且最多500字",400);}
 void event(long company,String type,long id,String action,Object before,Object after,String reason){db.update("INSERT INTO biz_personnel_change(company_id,record_type,record_id,action,before_value,after_value,reason,operator_id) VALUES(?,?,?,?,?,?,?,?)",company,type,id,action,String.valueOf(before),String.valueOf(after),reason,SecurityUtils.getUserId());}
 record Filter(String sql,List<Object> args){}
 Filter filter(long company,String keyword,String status){String where="company_id=?";List<Object> args=new ArrayList<>();args.add(company);if(keyword!=null&&!keyword.isBlank()){if(keyword.length()>100)throw new ServiceException("查询词过长",400);where+=" AND (real_name LIKE ? OR employee_no LIKE ? OR CAST(user_id AS CHAR)=?)";args.add("%"+keyword+"%");args.add("%"+keyword+"%");args.add(keyword);}if(status!=null&&!status.isBlank()){if(!Set.of("ACTIVE","LEFT").contains(status))throw new ServiceException("状态无效",400);where+=" AND status=?";args.add(status);}return new Filter(where,args);}
 public Map<String,Object> list(String keyword,String status,int page,int size){long c=company("biz:personnel:list");if(page<1||page>100000||size<1||size>100)throw new ServiceException("分页无效",400);Filter q=filter(c,keyword,status);long total=db.queryForObject("SELECT COUNT(*) FROM biz_employee_info WHERE "+q.sql,Long.class,q.args.toArray());var args=new ArrayList<>(q.args);args.add(size);args.add((page-1)*size);return Map.of("rows",db.queryForList("SELECT * FROM biz_employee_info WHERE "+q.sql+" ORDER BY id DESC LIMIT ? OFFSET ?",args.toArray()),"total",total);}
 public Map<String,Object> stats(){long c=company("biz:personnel:list");return db.queryForMap("SELECT COUNT(*) AS total,COALESCE(SUM(status='ACTIVE'),0) AS active,COALESCE(SUM(status='LEFT'),0) AS departed FROM biz_employee_info WHERE company_id=?",c);}
 public List<Map<String,Object>> candidates(){long c=company("biz:personnel:edit");return db.queryForList("SELECT u.user_id,u.nick_name FROM biz_company_user m JOIN sys_user u ON u.user_id=m.user_id WHERE m.company_id=? AND m.status='ACTIVE' AND u.status='0' AND u.del_flag='0' AND NOT EXISTS(SELECT 1 FROM biz_employee_info e WHERE e.company_id=m.company_id AND e.user_id=m.user_id) LIMIT 500",c);}
 @Transactional public void create(long user,EmployeeInput in){long c=company("biz:personnel:edit");employees.valid(in);if(in.employeeNo()==null||in.employeeNo().isBlank()||in.employeeNo().length()>40)throw new ServiceException("工号无效",400);employees.lock(user);if(!Long.valueOf(c).equals(employees.userCompany(user)))throw new AccessDeniedException("只能为已获本企业归属的账号补录档案");if(db.queryForObject("SELECT COUNT(*) FROM biz_employee_info WHERE company_id=? AND user_id=?",Long.class,c,user)>0)throw new ServiceException("档案已存在",409);db.update("INSERT INTO biz_employee_info(company_id,user_id,employee_no,real_name,contact_phone,job_title,entry_date,status,create_by) VALUES(?,?,?,?,?,?,CURRENT_DATE,'ACTIVE',?)",c,user,in.employeeNo(),in.realName(),in.contactPhone(),in.jobTitle(),SecurityUtils.getUsername());long id=db.queryForObject("SELECT id FROM biz_employee_info WHERE company_id=? AND user_id=?",Long.class,c,user);event(c,"EMPLOYEE",id,"CREATE","",in,"补录已授权账号档案");}
 @Transactional public void update(long id,EmployeeInput input,String reason){long c=company("biz:personnel:edit");reason(reason);var before=employees.staffDetail(id);employees.update(id,input,false);event(c,"EMPLOYEE",id,"UPDATE",before,employees.staffDetail(id),reason);}
 @Transactional public void leave(long id,Integer version,String reason){long c=company("biz:personnel:leave");reason(reason);var old=employees.staffDetail(id);long user=((Number)old.get("user_id")).longValue();employees.lock(user);var row=db.queryForMap("SELECT * FROM biz_employee_info WHERE company_id=? AND id=? FOR UPDATE",c,id);if(user==SecurityUtils.getUserId()||user==1||employees.hasRole(user,"company_admin")||employees.hasRole(user,"platform_admin"))throw new AccessDeniedException("不能办理本人或管理员离职");if(!"ACTIVE".equals(row.get("status"))||version==null||version.intValue()!=((Number)row.get("version")).intValue())throw new ServiceException("状态或版本已变化",409);if(db.queryForObject("SELECT COUNT(*) FROM biz_task_assignment WHERE company_id=? AND user_id=? AND status NOT IN ('COMPLETED','CANCELLED')",Long.class,c,user)>0)throw new ServiceException("员工有未结束任务，请先交接",409);
 db.update("UPDATE biz_employee_info SET status='LEFT',leave_date=CURRENT_DATE,version=version+1,update_by=? WHERE id=? AND company_id=?",SecurityUtils.getUsername(),id,c);db.update("UPDATE biz_company_user SET status='LEFT' WHERE company_id=? AND user_id=?",c,user);db.update("DELETE ur FROM sys_user_role ur JOIN sys_role r ON r.role_id=ur.role_id WHERE ur.user_id=? AND r.role_key IN ('employee','company_hr','company_business','company_finance')",user);int n=db.update("INSERT IGNORE INTO sys_user_role(user_id,role_id) SELECT ?,role_id FROM sys_role WHERE role_key='company_applicant' AND status='0' AND del_flag='0'",user);if(!employees.hasRole(user,"company_applicant"))throw new ServiceException("申请人角色配置异常",409);
 var grants=db.queryForList("SELECT * FROM biz_access_permission WHERE company_id=? AND user_id=? AND status='ACTIVE' FOR UPDATE",c,user);for(var grant:grants){long gid=((Number)grant.get("id")).longValue();db.update("UPDATE biz_access_permission SET status='REVOKED',sync_status='NOT_CONNECTED',version=version+1,update_by=? WHERE id=? AND company_id=?",SecurityUtils.getUsername(),gid,c);event(c,"ACCESS",gid,"REVOKE",grant,"REVOKED",reason);}event(c,"EMPLOYEE",id,"LEAVE",row,"LEFT",reason);employees.invalidate(user);}
 public List<Map<String,Object>> history(String type,long id){long c=company(type.equals("ACCESS")?"biz:access:list":"biz:personnel:list");if(!Set.of("ACCESS","EMPLOYEE").contains(type))throw new ServiceException("类型无效",400);String table=type.equals("ACCESS")?"biz_access_permission":"biz_employee_info";if(db.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE id=? AND company_id=?",Long.class,id,c)!=1)throw new ServiceException("记录不存在或无权访问",404);return db.queryForList("SELECT * FROM biz_personnel_change WHERE company_id=? AND record_type=? AND record_id=? ORDER BY id DESC",c,type,id);}
 public byte[] export(String keyword,String status){long c=company("biz:personnel:export");Filter q=filter(c,keyword,status);var rows=db.queryForList("SELECT id,employee_no,real_name,contact_phone,job_title,status,entry_date,leave_date FROM biz_employee_info WHERE "+q.sql+" ORDER BY id LIMIT 10001",q.args.toArray());if(rows.size()>10000)throw new ServiceException("超过10000条，请缩小筛选范围",413);StringBuilder csv=new StringBuilder("\ufeff编号,工号,姓名,电话,岗位,状态,入职日期,离职日期\r\n");String[] keys={"id","employee_no","real_name","contact_phone","job_title","status","entry_date","leave_date"};for(var row:rows){for(int i=0;i<keys.length;i++){if(i>0)csv.append(',');String v=Objects.toString(row.get(keys[i]),"");String clean=v.stripLeading();if(!clean.isEmpty()&&"=+-@".indexOf(clean.charAt(0))>=0||v.startsWith("\t")||v.startsWith("\r"))v="'"+v;csv.append('"').append(v.replace("\"","\"\"")).append('"');}csv.append("\r\n");}return csv.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);}
 public record GrantInput(Long userId,String deviceCode,LocalDateTime validFrom,LocalDateTime validTo,Integer version,String reason){}
 public Map<String,Object> grants(int page,int size){long c=company("biz:access:list");if(page<1||page>100000||size<1||size>100)throw new ServiceException("分页无效",400);return Map.of("rows",db.queryForList("SELECT g.*,e.real_name,CASE WHEN g.status='REVOKED' THEN 'REVOKED' WHEN e.status<>'ACTIVE' THEN 'LEFT' WHEN g.status<>'ACTIVE' OR g.valid_from IS NULL OR g.valid_to IS NULL THEN 'INACTIVE' WHEN g.valid_from>CURRENT_TIMESTAMP THEN 'NOT_STARTED' WHEN g.valid_to<CURRENT_TIMESTAMP THEN 'EXPIRED' ELSE 'VALID' END AS record_state FROM biz_access_permission g JOIN biz_employee_info e ON e.company_id=g.company_id AND e.user_id=g.user_id WHERE g.company_id=? ORDER BY g.id DESC LIMIT ? OFFSET ?",c,size,(page-1)*size),"total",db.queryForObject("SELECT COUNT(*) FROM biz_access_permission WHERE company_id=?",Long.class,c));}
 @Transactional public long grant(Long id,GrantInput in){long c=company("biz:access:edit");reason(in.reason());if(in.userId()==null||in.deviceCode()==null||!in.deviceCode().matches("[A-Za-z0-9_-]{1,80}")||in.validFrom()==null||in.validTo()==null||!in.validTo().isAfter(in.validFrom())||!in.validTo().isAfter(LocalDateTime.now()))throw new ServiceException("员工、门禁点编号或有效期无效",400);employees.lock(in.userId());if(!Long.valueOf(c).equals(employees.userCompany(in.userId()))||db.queryForObject("SELECT COUNT(*) FROM biz_employee_info WHERE company_id=? AND user_id=? AND status='ACTIVE'",Long.class,c,in.userId())!=1)throw new AccessDeniedException("只能授权本企业在职员工");
 if(id==null){if(db.queryForObject("SELECT COUNT(*) FROM biz_access_permission WHERE company_id=? AND user_id=? AND device_code=?",Long.class,c,in.userId(),in.deviceCode())>0)throw new ServiceException("该门禁记录已存在，请修改原记录",409);db.update("INSERT INTO biz_access_permission(company_id,user_id,device_code,valid_from,valid_to,status,sync_status,create_by) VALUES(?,?,?,?,?,'ACTIVE','NOT_CONNECTED',?)",c,in.userId(),in.deviceCode(),in.validFrom(),in.validTo(),SecurityUtils.getUsername());long gid=db.queryForObject("SELECT id FROM biz_access_permission WHERE company_id=? AND user_id=? AND device_code=?",Long.class,c,in.userId(),in.deviceCode());event(c,"ACCESS",gid,"GRANT","",in,in.reason());return gid;}
 var rows=db.queryForList("SELECT * FROM biz_access_permission WHERE id=? AND company_id=? FOR UPDATE",id,c);if(rows.isEmpty())throw new ServiceException("授权不存在或无权访问",404);var old=rows.get(0);if(in.userId().longValue()!=((Number)old.get("user_id")).longValue()||!in.deviceCode().equals(old.get("device_code")))throw new ServiceException("不能转移员工或门禁点",400);if(in.version()==null||db.update("UPDATE biz_access_permission SET valid_from=?,valid_to=?,status='ACTIVE',sync_status='NOT_CONNECTED',version=version+1,update_by=? WHERE id=? AND company_id=? AND version=?",in.validFrom(),in.validTo(),SecurityUtils.getUsername(),id,c,in.version())!=1)throw new ServiceException("版本冲突",409);event(c,"ACCESS",id,"UPDATE",old,in,in.reason());return id;}
 @Transactional public void revoke(long id,Integer version,String reason){long c=company("biz:access:edit");reason(reason);var rows=db.queryForList("SELECT * FROM biz_access_permission WHERE id=? AND company_id=? FOR UPDATE",id,c);if(rows.isEmpty())throw new ServiceException("授权不存在或无权访问",404);var old=rows.get(0);if(!"ACTIVE".equals(old.get("status"))||version==null||db.update("UPDATE biz_access_permission SET status='REVOKED',sync_status='NOT_CONNECTED',version=version+1,update_by=? WHERE id=? AND company_id=? AND version=?",SecurityUtils.getUsername(),id,c,version)!=1)throw new ServiceException("状态或版本冲突",409);event(c,"ACCESS",id,"REVOKE",old,"REVOKED",reason);}
}
